\set ON_ERROR_STOP on
begin;
create function public.test_assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',msg;end if;end$$;
create function public.test_raises(stmt text,expected text) returns void language plpgsql as $$begin execute stmt;raise exception 'Expected failure: %',expected;exception when others then if sqlerrm not like '%'||expected||'%' then raise;end if;end$$;
insert into auth.users(id,raw_user_meta_data) values('00000000-0000-0000-0000-000000000001','{"full_name":"Owner","role":"admin"}'),('00000000-0000-0000-0000-000000000002','{"full_name":"Other Owner"}'),('00000000-0000-0000-0000-000000000003','{"full_name":"Nurse One"}'),('00000000-0000-0000-0000-000000000004','{"full_name":"Nurse Two"}'),('00000000-0000-0000-0000-000000000005','{"full_name":"Admin"}'),('00000000-0000-0000-0000-000000000006','{"full_name":"Unconfirmed"}');
update auth.users set email_confirmed_at=null where id='00000000-0000-0000-0000-000000000006';
update profiles set role='admin',onboarding_completed=true where id='00000000-0000-0000-0000-000000000005';
select test_assert((select role='nurse' from profiles where id='00000000-0000-0000-0000-000000000001'),'signup metadata cannot grant admin role');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',true);
select test_raises($s$select complete_onboarding('{"account_type":"nurse","full_name":"Unconfirmed"}')$s$,'Confirm your email');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select test_raises($s$select complete_onboarding('{"account_type":"admin","full_name":"Owner"}')$s$,'Choose a facility or nurse');
select complete_onboarding('{"account_type":"facility","full_name":"Owner","facility_name":"Facility A","city":"Charlotte","state":"NC","address":"100 Main Street"}');
select set_config('test.facility',my_facility()::text,true);
select complete_onboarding('{"account_type":"facility","full_name":"Owner","facility_name":"Duplicate","city":"Charlotte","state":"NC","address":"100 Main Street"}');
select test_assert((select count(*)=1 from facilities),'facility onboarding is idempotent');
select test_assert((select role='facility' and onboarding_completed from profiles where id=auth.uid()),'real facility account created');
select set_config('test.shift',manage_shift('create',null,jsonb_build_object('title','RN Med Surg','specialty','RN','department','Med Surg','starts_at',now()+interval '1 day','ends_at',now()+interval '1 day 12 hours','hourly_rate',52,'urgent',false,'notes','BLS required'))::text,true);
select set_config('test.shift_id',(current_setting('test.shift')::jsonb->>'id'),true);
select test_assert((current_setting('test.shift')::jsonb->>'status')='draft','creation persists a draft');
select test_raises($s$select manage_shift('publish',current_setting('test.shift_id')::uuid,current_setting('test.shift')::jsonb)$s$,'must be verified');
select set_config('test.edited',manage_shift('edit',current_setting('test.shift_id')::uuid,(current_setting('test.shift')::jsonb)||jsonb_build_object('title','RN Updated'))::text,true);
select test_raises($s$select manage_shift('edit',current_setting('test.shift_id')::uuid,current_setting('test.shift')::jsonb)$s$,'changed');
select test_raises($s$insert into shifts(facility_id,title,specialty,starts_at,ends_at,hourly_rate) values(my_facility(),'Bypass','RN',now()+interval '1 day',now()+interval '2 days',52)$s$,'permission denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select complete_onboarding('{"account_type":"facility","full_name":"Other Owner","facility_name":"Facility B","city":"Raleigh","state":"NC","address":"200 Main Street"}');
select test_assert((select count(*)=0 from shifts),'other facility cannot read drafts');
select test_raises($s$select manage_shift('edit',current_setting('test.shift_id')::uuid,current_setting('test.edited')::jsonb)$s$,'Shift not found');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select complete_onboarding('{"account_type":"nurse","full_name":"Nurse One"}');
select test_assert((select count(*)=0 from shifts),'nurses cannot see drafts');
select save_professional_profile(jsonb_build_object('full_name','Nurse One','credential','RN','specialty','Critical Care','city','Charlotte','state','NC','experience_years',5,'bio','Critical care nursing','license_number','RN-TEST-100','license_state','NC','license_expires',current_date+365));
select test_assert((select not verified and credential='RN' from profiles where id=auth.uid()),'profile changes do not self-verify');
select test_raises($s$select staffing_action('verify_nurse','{"user_id":"00000000-0000-0000-0000-000000000003","credential":"RN","verified":true}')$s$,'Forbidden');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',true);
select staffing_action('verify_facility',jsonb_build_object('facility_id',current_setting('test.facility'),'status','verified'));
select staffing_action('verify_nurse','{"user_id":"00000000-0000-0000-0000-000000000003","credential":"RN","verified":true}');
select test_assert((select count(*)=1 from nurse_credentials),'admin can review license data');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select test_assert((select count(*)=0 from nurse_credentials),'facility cannot read private license numbers');
select test_raises($s$select manage_shift('publish',current_setting('test.shift_id')::uuid,current_setting('test.edited')::jsonb)$s$,'active facility subscription');
reset role;
select sync_subscription('evt_real_test',200,current_setting('test.facility')::uuid,'cus_real_test','sub_real_test','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select set_config('test.published',manage_shift('publish',current_setting('test.shift_id')::uuid,current_setting('test.edited')::jsonb)::text,true);
select test_assert((current_setting('test.published')::jsonb->>'status')='open','verified subscribed facility can publish');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select test_assert((select count(*)=1 from shifts),'published shift visible to nurse');
select staffing_action('apply',jsonb_build_object('shift_id',current_setting('test.shift_id')));
select set_config('test.application',(select id::text from applications where nurse_id=auth.uid()),true);
select staffing_action('withdraw',jsonb_build_object('application_id',current_setting('test.application')));
select test_assert((select status='withdrawn' from applications where nurse_id=auth.uid()),'withdrawal persists');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select complete_onboarding('{"account_type":"nurse","full_name":"Nurse Two"}');
select save_professional_profile(jsonb_build_object('full_name','Nurse Two','credential','RN','specialty','Medical Surgical','city','Charlotte','state','NC','experience_years',3,'bio','','license_number','RN-TEST-200','license_state','NC','license_expires',current_date+365));
select test_raises($s$select staffing_action('apply',jsonb_build_object('shift_id',current_setting('test.shift_id')))$s$,'verified current nursing license');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',true);
select staffing_action('verify_nurse','{"user_id":"00000000-0000-0000-0000-000000000004","credential":"RN","verified":true}');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select staffing_action('apply',jsonb_build_object('shift_id',current_setting('test.shift_id')));
select set_config('test.application2',(select id::text from applications where nurse_id=auth.uid()),true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select test_raises($s$select manage_shift('edit',current_setting('test.shift_id')::uuid,current_setting('test.published')::jsonb)$s$,'has applications');
select staffing_action('accept',jsonb_build_object('application_id',current_setting('test.application2')));
select test_assert((select status='filled' and assigned_nurse_id='00000000-0000-0000-0000-000000000004' from shifts where id=current_setting('test.shift_id')::uuid),'acceptance makes a real booking');
select test_raises($s$select staffing_action_v1('create_facility','{"name":"Bypass"}')$s$,'permission denied');
select set_config('test.latest',(select to_jsonb(s)::text from shifts s where s.id=current_setting('test.shift_id')::uuid),true);
select manage_shift('cancel',current_setting('test.shift_id')::uuid,current_setting('test.latest')::jsonb);
select test_assert((select status='cancelled' from shifts where id=current_setting('test.shift_id')::uuid),'cancellation is persisted');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select test_assert(exists(select 1 from notifications where title='Shift cancelled'),'booked nurse notified of cancellation');
select save_professional_profile(jsonb_build_object('full_name','Nurse Two','credential','RN','specialty','Medical Surgical','city','Charlotte','state','NC','experience_years',3,'bio','','license_number','RN-TEST-201','license_state','NC','license_expires',current_date+365));
select test_assert((select not verified from profiles where id=auth.uid()),'license edit resets verification');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',true);
select staffing_action('suspend_user','{"user_id":"00000000-0000-0000-0000-000000000004","suspended":true}');
select test_raises($s$select staffing_action('suspend_user','{"user_id":"00000000-0000-0000-0000-000000000005","suspended":true}')$s$,'non-administrator');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select test_assert((select count(*)=0 from shifts),'suspended account loses RLS access');
select test_raises($s$select staffing_action('read_notification','{"notification_id":"00000000-0000-0000-0000-000000000001"}')$s$,'Active registered account');
reset role;
select 'PASS: real onboarding, profile/privacy, draft/edit/publish/cancel, verified booking, subscription gates, suspended-user RLS and legacy RPC isolation' as result;
rollback;
